#include <iostream>
#include <algorithm>
using namespace std;

long long int sequence_vals[18];
int min_moves_result=0;

void dfs(int current_moves, long long int remaining, int position)
{
    if(current_moves > min_moves_result)
        return;
    if(remaining == 0)
    {
        min_moves_result = min(min_moves_result, current_moves);
        return;
    }
    int needed = remaining / sequence_vals[position];
    dfs(current_moves + position * needed++, remaining - needed * sequence_vals[position], position - 1);
    dfs(current_moves + needed * position, needed * sequence_vals[position] - remaining, position - 1);
}

int main()
{
    long long int val_input;
    cin >> val_input;
    sequence_vals[1] = 1;
    for(int i=2; i<18; i++)
        sequence_vals[i] = sequence_vals[i-1] * 10 + 1;
    long long int temp_val = val_input;
    min_moves_result = 0;
    while(temp_val > 0)
    {
        for(int i=1; i<18; i++)
        {
            if(sequence_vals[i] > temp_val)
            {
                min_moves_result += (i - 1);
                temp_val -= sequence_vals[i - 1];
                break;
            }
        }
    }
    dfs(0, val_input, 16);
    cout << min_moves_result << endl;
}
